<div class="precision-legend" aria-label="Map symbol legend"><strong>Map symbols</strong><span><i class="glyph exact"></i> Exact site</span><span><i class="glyph cluster"></i> Parent cluster</span><span><i class="glyph cluster city"></i> CITY aggregate</span><span><i class="glyph cluster coarse"></i> AREA aggregate</span><span><i class="glyph unmapped"></i> No mapped location</span><small>Pin color: <b class="poultry"></b>Poultry <b class="pig"></b>Pig <b class="dairy"></b>Dairy <b class="processing"></b>Processing <b class="laboratory"></b>Lab <b class="aquaculture"></b>Aquaculture</small></div>
<style>.precision-legend{position:absolute;z-index:2;bottom:1rem;left:1rem;display:grid;gap:.28rem;padding:.6rem;border:1px solid #48504b;background:#171a18e8;color:#f1efe8;font:.65rem system-ui}.precision-legend strong{font-size:.65rem}.precision-legend small{display:flex;max-width:15rem;flex-wrap:wrap;gap:.25rem;align-items:center;color:#c6cbc4;font-size:.54rem}.precision-legend b{width:.45rem;height:.45rem;border-radius:50%;background:#c83232}.precision-legend .pig{background:#8c8c8c}.precision-legend .dairy{background:#7f5c9c}.precision-legend .processing{background:#ccb44f}.precision-legend .laboratory{background:#d47b30}.precision-legend .aquaculture{background:#39804e}.glyph{display:inline-block;width:.72rem;height:.72rem;margin-right:.35rem;vertical-align:-.1rem}.exact{width:.52rem;height:.78rem;border:2px solid #fff;border-radius:55% 55% 55% 0;background:#c83232;box-shadow:0 1px 2px #0008;transform:rotate(-45deg)}.cluster{border-radius:50%;background:#6ecc39;box-shadow:0 0 0 4px #b5e28c}.cluster.city{outline:2px solid #315b83}.cluster.coarse{outline:2px solid #6b4f2f}.unmapped{height:.35rem;border-bottom:1px solid #e9ebe6}@media(max-width:40rem){.precision-legend{bottom:.65rem;left:.65rem;font-size:.58rem}}</style>
